input.new_string:
const matchesSearch = useCallback(
	(label: string) => label.toLowerCase().includes(searchValue.toLowerCase()),
	[searchValue],
);

const visibleActions = actionCommands.filter(
	(cmd) => (cmd.visible ?? true) && (!isSearchMode || matchesSearch(cmd.label)),
);
const showNoResults =
	!hasSearchResults && !isPendingSearch && isSearchMode && visibleActions.length === 0;

input.old_string:
{!isSearchMode && visibleActions.length > 0 && (
	<CommandGroup heading='Actions'>
		{visibleActions.map((command) => (
			<CommandItem
				key={command.id}
				value={command.id}
				onSelect={() => runCommand(command.action)}
			>
				<command.icon />
				<span>{command.label}</span>
				{command.shortcut && <CommandShortcut>{command.shortcut}</CommandShortcut>}
			</CommandItem>
		))}
	</CommandGroup>
)}
